  });

  const origKey = Buffer.from(res.responseKey);
  const origCipher = Buffer.from(res.ciphertextBody);

  // Clobber all of WASM linear memory with 0xFF!
  const mem = new Uint8Array(instance.exports.memory.buffer);
  mem.fill(0xFF);

  // Check if res.responseKey or res.ciphertextBody changed!
  if (!res.responseKey.equals(origKey)) {
